import { useContext, useState } from 'react';
import AuthContext from '../context/AuthContext';

function Login() {
  const { login } = useContext(AuthContext);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState(null);

  const submit = async (e) => {
    e.preventDefault();
    try {
      await login(email, password);
      window.location.href = '/';
    } catch (err) {
      console.error('Login error', err);
      const msg = err?.response?.data?.error || err?.message || 'Login failed';
      setError(msg);
    }
  };

  return (
    <div className="page mt-0" style={{ minHeight: 'calc(100vh - 72px)', display: 'flex', alignItems: 'center', background: 'linear-gradient(135deg, #f8fafc 0%, #ffffff 100%)' }}>
      <div className="container flex justify-center">
        <div className="card max-w-md w-full animate-in slide-in-from-bottom-4" style={{ padding: '56px' }}>
          <header className="text-center mb-10">
            <h2 className="text-xl mb-2 font-black">Intelligence Access</h2>
            <p className="muted small font-bold uppercase tracking-widest">Sign in to your analytical dashboard</p>
          </header>

          <form onSubmit={submit} className="space-y-6">
            <div className="space-y-2">
              <label className="text-[10px] uppercase font-black tracking-widest muted">Corporate Email</label>
              <input
                type="email"
                className="form-input"
                placeholder="name@company.com"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
              />
            </div>

            <div className="space-y-2">
              <label className="text-[10px] uppercase font-black tracking-widest muted">Security Key</label>
              <input
                type="password"
                className="form-input"
                placeholder="••••••••"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
              />
            </div>

            {error && (
              <div className="bg-danger-soft text-danger p-4 rounded-xl text-xs font-bold border border-transparent">
                {error}
              </div>
            )}

            <div className="pt-4">
              <button type="submit" className="btn btn-primary w-full py-4 text-base">Authorize Session</button>
            </div>

            <p className="muted text-xs text-center mt-8 font-medium">
              New to the platform? <a href="/signup" style={{ color: 'var(--accent)', fontWeight: '800', textDecoration: 'none' }}>Initialize Account</a>
            </p>
          </form>
        </div>
      </div>
    </div>
  );
}

export default Login;
